her.customCSS:
:root {
	--gem-blue: #4285f4;
	--gem-purple: #9b72cb;
	--gem-red: #d96570;
	--gem-yellow: #f6b73c;
	--gem-a: 30%;         /* glow strength, light mode */
	--gem-a-low: 20%;     /* strength at the dim point of the breath */
	--gem-fade-in: 4s;    /* initial fade-in */
	--gem-breathe: 8s;    /* one full pulse */
	--gem-fade-out: 1.8s; /* fade-away when the chat starts */
}
html.dark {
	--gem-a: 42%;
	--gem-a-low: 26%;
}

/* The glow only exists while the chat is EMPTY (new chat). Once any message exists
   (existing chat opened, or first message sent) the rule below stops matching, so the
   glow is suppressed entirely and the input is a normal, unstyled input again.
   Open WebUI itself renders the input inside the new-chat placeholder (under the model
   name/description) while empty, and swaps it for the bottom-docked input once the first
   message is sent. */
html:not(:has(#messages-container [id^="message-"]:not([id^="message-input"]))) #message-input-container {
	box-shadow:
		-14px 6px 46px -6px transparent,
		0 -2px 50px -8px transparent,
		14px 6px 46px -6px transparent,
		0 14px 54px -4px transparent;
	animation:
		gem-in var(--gem-fade-in) cubic-bezier(0.25, 0.1, 0.25, 1) both,
		gem-breathe var(--gem-breathe) ease-in-out var(--gem-fade-in) infinite;
}

@keyframes gem-in {
	from {
		box-shadow:
			-14px 6px 46px -6px color-mix(in srgb, var(--gem-blue) 0%, transparent),
			0 -2px 50px -8px color-mix(in srgb, var(--gem-purple) 0%, transparent),
			14px 6px 46px -6px color-mix(in srgb, var(--gem-red) 0%, transparent),
			0 14px 54px -4px color-mix(in srgb, var(--gem-yellow) 0%, transparent);
	}
	to {
		box-shadow:
			-14px 6px 46px -6px color-mix(in srgb, var(--gem-blue) var(--gem-a), transparent),
			0 -2px 50px -8px color-mix(in srgb, var(--gem-purple) var(--gem-a), transparent),
			14px 6px 46px -6px color-mix(in srgb, var(--gem-red) var(--gem-a), transparent),
			0 14px 54px -4px color-mix(in srgb, var(--gem-yellow) calc(var(--gem-a) * 0.7), transparent);
	}
}

@keyframes gem-breathe {
	0%, 100% {
		box-shadow:
			-14px 6px 46px -6px color-mix(in srgb, var(--gem-blue) var(--gem-a), transparent),
			0 -2px 50px -8px color-mix(in srgb, var(--gem-purple) var(--gem-a), transparent),
			14px 6px 46px -6px color-mix(in srgb, var(--gem-red) var(--gem-a), transparent),
			0 14px 54px -4px color-mix(in srgb, var(--gem-yellow) calc(var(--gem-a) * 0.7), transparent);
	}
	50% {
		box-shadow:
			-20px 8px 64px -4px color-mix(in srgb, var(--gem-blue) var(--gem-a-low), transparent),
			0 -4px 70px -4px color-mix(in srgb, var(--gem-purple) var(--gem-a-low), transparent),
			20px 8px 64px -4px color-mix(in srgb, var(--gem-red) var(--gem-a-low), transparent),
			0 20px 74px 0 color-mix(in srgb, var(--gem-yellow) calc(var(--gem-a-low) * 0.7), transparent);
	}
}

@keyframes gem-out {
	from {
		box-shadow:
			-14px 6px 46px -6px color-mix(in srgb, var(--gem-blue) var(--gem-a), transparent),
			0 -2px 50px -8px color-mix(in srgb, var(--gem-purple) var(--gem-a), transparent),
			14px 6px 46px -6px color-mix(in srgb, var(--gem-red) var(--gem-a), transparent),
			0 14px 54px -4px color-mix(in srgb, var(--gem-yellow) calc(var(--gem-a) * 0.7), transparent);
	}
	to {
		box-shadow:
			-14px 6px 46px -6px color-mix(in srgb, var(--gem-blue) 0%, transparent),
			0 -2px 50px -8px color-mix(in srgb, var(--gem-purple) 0%, transparent),
			14px 6px 46px -6px color-mix(in srgb, var(--gem-red) 0%, transparent),
			0 14px 54px -4px color-mix(in srgb, var(--gem-yellow) 0%, transparent);
	}
}

/* ---- Focus glowbar (liquid glass) ----
   While the input is focused (empty chat only), a thin, translucent rim of soft color
   drifts slowly around the outline, like light refracting through glass. Pieces of the
   rim fade to nearly clear, with a pale specular highlight, so it never reads as a
   solid neon stripe. A wide diffuse bloom adds depth.
   Animates background-position (no @property), so it is smooth.
   Tune: --gem-bar-width (rim thickness), --gem-bar-speed (drift), --gem-bar-bloom (blur),
         --gem-bar-strength (overall rim opacity, 0-1). */
:root {
	--gem-bar-width: 1.5px;
	--gem-bar-speed: 12s;
	--gem-bar-bloom: 18px;
	--gem-bar-strength: 0.7;
	--gem-glass-hi: rgba(255, 255, 255, 0.85);
}

html:not(:has(#messages-container [id^="message-"]:not([id^="message-input"]))) #message-input-container {
	position: relative;
}
html:not(:has(#messages-container [id^="message-"]:not([id^="message-input"]))) #message-input-container::before,
html:not(:has(#messages-container [id^="message-"]:not([id^="message-input"]))) #message-input-container::after {
	content: "";
	position: absolute;
	inset: 0;
	border-radius: inherit;
	padding: var(--gem-bar-width);
	pointer-events: none;
	opacity: 0;
	transition: opacity 1.1s ease;
	background: linear-gradient(90deg,
		color-mix(in srgb, var(--gem-blue) 55%, transparent),
		color-mix(in srgb, var(--gem-purple) 45%, transparent) 14%,
		var(--gem-glass-hi) 22%,
		color-mix(in srgb, var(--gem-red) 30%, transparent) 32%,
		color-mix(in srgb, var(--gem-yellow) 30%, transparent) 46%,
		color-mix(in srgb, var(--gem-blue) 12%, transparent) 58%,
		color-mix(in srgb, var(--gem-blue) 55%, transparent) 72%,
		var(--gem-glass-hi) 80%,
		color-mix(in srgb, var(--gem-purple) 40%, transparent) 90%,
		color-mix(in srgb, var(--gem-blue) 55%, transparent)) 0 0 / 300% 100%;
	-webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
	-webkit-mask-composite: xor;
	mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
	animation: gem-bar var(--gem-bar-speed) ease-in-out infinite alternate;
}
/* Diffuse bloom: wide, soft and low-opacity, hugging the edge like refracted light. */
html:not(:has(#messages-container [id^="message-"]:not([id^="message-input"]))) #message-input-container::after {
	filter: blur(var(--gem-bar-bloom)) saturate(1.1);
	padding: calc(var(--gem-bar-width) + 5px);
}
html:not(:has(#messages-container [id^="message-"]:not([id^="message-input"]))) #message-input-container:focus-within::before {
	opacity: var(--gem-bar-strength);
}
html:not(:has(#messages-container [id^="message-"]:not([id^="message-input"]))) #message-input-container:focus-within::after {
	opacity: 0.35;
}
@keyframes gem-bar {
	from { background-position: 0% 0; }
	to   { background-position: 100% 0; }
}

/* Gemini-style send button */
#send-message-button:enabled {
	background-image: linear-gradient(135deg, var(--gem-blue), var(--gem-purple) 60%, var(--gem-red));
	color: #fff;
	box-shadow: 0 0 14px color-mix(in srgb, var(--gem-purple) 45%, transparent);
}

@media (prefers-reduced-motion: reduce) {
	html:not(:has(#messages-container [id^="message-"]:not([id^="message-input"]))) #message-input-container {
		animation: gem-in 0.01s both;
	}
	html:not(:has(#messages-container [id^="message-"]:not([id^="message-input"]))) #message-input-container::before,
	html:not(:has(#messages-container [id^="message-"]:not([id^="message-input"]))) #message-input-container::after {
		animation: none;
	}
